// Python repr() emulation helpers.

// Non-printable per Python str.isprintable(): general categories C* (Cc, Cf,
// Cs, Co, Cn-unassigned) and separators Zl/Zp/Zs, with U+0020 SPACE excepted.
const NON_PRINTABLE = /[\p{C}\p{Zl}\p{Zp}\p{Zs}]/u;

function isPrintable(ch) {
  if (ch === ' ') return true;
  return !NON_PRINTABLE.test(ch);
}

function hexEscape(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

// Python repr() of a str.
export function pyStrRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (isPrintable(ch)) out += ch;
    else out += hexEscape(cp);
  }
  return out + quote;
}

// Python repr() of a bytes object. `s` is a JS string whose char codes are
// treated as byte values (our content is ASCII).
export function pyBytesRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = 'b' + quote;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const b = s.charCodeAt(i) & 0xff;
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (b >= 0x20 && b <= 0x7e) out += ch;
    else out += '\\x' + b.toString(16).padStart(2, '0');
  }
  return out + quote;
}

// Python str() of a bool.
export function pyBool(b) {
  return b ? 'True' : 'False';
}

// Minimal Python argparse clone for:
//   parser.add_argument('--domain', type=str, required=True)
//   parser.add_argument('--strict', type=bool, required=True, default=False)
// Replicates Python 3.10+ argparse behavior with prog name 'test3_executable'.

const PROG = 'test3_executable';
const USAGE = `usage: ${PROG} [-h] --domain DOMAIN --strict STRICT\n`;
const HELP =
  USAGE +
  '\n' +
  'options:\n' +
  '  -h, --help       show this help message and exit\n' +
  '  --domain DOMAIN\n' +
  '  --strict STRICT\n';

const LONG_OPTIONS = ['--help', '--domain', '--strict'];

// Matches argparse's _negative_number_matcher; the parser has no
// negative-number-like options, so these are treated as values.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function error(message) {
  process.stderr.write(USAGE);
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

function printHelpAndExit() {
  process.stdout.write(HELP);
  process.exit(0);
}

// Mirrors argparse._parse_optional: does this token look like an option
// string (and therefore cannot be consumed as an option's value)?
function isOptionLike(tok) {
  if (!tok.startsWith('-')) return false; // plain value
  if (tok === '-') return false; // single '-' is a value
  if (NEGATIVE_NUMBER.test(tok)) return false; // negative number
  if (tok.includes(' ')) return false; // contains a space -> value
  return true;
}

export function parseArgs(argv) {
  const values = { domain: undefined, strict: undefined };
  const seen = new Set();
  const extras = [];
  let afterDoubleDash = false;

  for (let i = 0; i < argv.length; i++) {
    const tok = argv[i];

    if (afterDoubleDash) {
      extras.push(tok);
      continue;
    }
    // This argparse version reports '--' itself (and everything after) as
    // unrecognized when no positional consumes it.
    if (tok === '--') {
      afterDoubleDash = true;
      extras.push(tok);
      continue;
    }

    if (tok.startsWith('--')) {
      let name = tok;
      let value;
      let hasEq = false;
      const eq = tok.indexOf('=');
      if (eq !== -1) {
        name = tok.slice(0, eq);
        value = tok.slice(eq + 1);
        hasEq = true;
      }
      if (name === '--') {
        // '--=...' and friends: not a valid option string
        extras.push(tok);
        continue;
      }
      // Exact match, else unambiguous prefix (allow_abbrev).
      let matches;
      if (LONG_OPTIONS.includes(name)) matches = [name];
      else matches = LONG_OPTIONS.filter((o) => o.startsWith(name));

      if (matches.length > 1) {
        error(`ambiguous option: ${name} could match ${matches.join(', ')}`);
      }
      if (matches.length === 0) {
        extras.push(tok);
        continue;
      }
      const opt = matches[0];
      if (opt === '--help') printHelpAndExit();

      if (!hasEq) {
        if (i + 1 >= argv.length || isOptionLike(argv[i + 1])) {
          error(`argument ${opt}: expected one argument`);
        }
        value = argv[++i];
      }
      if (opt === '--domain') {
        values.domain = value;
        seen.add('--domain');
      } else {
        values.strict = value;
        seen.add('--strict');
      }
      continue;
    }

    if (isOptionLike(tok)) {
      // Short-option territory; only -h is defined.
      if (tok === '-h') printHelpAndExit();
      extras.push(tok);
      continue;
    }

    // Bare value with no positionals defined -> unrecognized.
    extras.push(tok);
  }

  const missing = [];
  if (!seen.has('--domain')) missing.push('--domain');
  if (!seen.has('--strict')) missing.push('--strict');
  if (missing.length > 0) {
    error(`the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    error(`unrecognized arguments: ${extras.join(' ')}`);
  }

  // type=bool on a str: Python bool(str) — only '' is falsy.
  return { domain: values.domain, strict: values.strict.length > 0 };
}

// Harness: parse argv with the argparse clone and print the result as JSON.
import { parseArgs } from '../lib/argparse.mjs';

const result = parseArgs(process.argv.slice(2));
process.stdout.write(JSON.stringify(result) + '\n');

// Verification for /output/lib/pyrepr.mjs and /output/lib/argparse.mjs.
// (a) Unit-tests pyrepr against hand-computed Python repr() expectations.
// (b) Runs a matrix of argv vectors through both the reference executable and
//     the node harness (tools/argparse-harness.mjs), comparing stderr and exit
//     code byte-for-byte, plus stdout for help/error cases; for successful
